"""Render computed research evidence; never substitute planned or invented results."""
import argparse
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import numpy as np
from research.common import ROOT,OUT,SOURCE,RUN,CALIBRATORS,require_audit,read_json,save_json,digest

LIMITATIONS=['Retrospective single-source VitalDB evaluation, not external validation.','Survivor-only selection excludes in-hospital deaths and changes the prediction population.','Prolonged stay is a training-derived statistical upper-quartile endpoint, not an established clinical cutoff.','The same holdout was previously examined; these are secondary exploratory analyses, not a new independent test.','No prospective clinical validation or deployment readiness has been established.','Surgical complexity, duration, case mix and hospital discharge practices may confound associations.','Bootstrap uncertainty is conditional on fitted models and fixed labels; single-seed ablations do not measure training variability.','Multiple exploratory comparisons and subgroup analyses are unadjusted for multiplicity.','Recordings are capped at 720 minutes; transient within-minute artifacts may survive aggregation.','Attribution does not establish causality; fixed missingness is not itself attributed.']

def load():
    audit=require_audit()
    models={name:read_json(ROOT/f'results/runs/{SOURCE}/metrics/{name}.json') for name in ['transformer','gru','xgboost']}
    paired=read_json(OUT/'paired/comparison.json'); calibration=read_json(OUT/'calibration/summary.json'); subgroups=read_json(OUT/'subgroups/summary.json'); ablations=read_json(OUT/'ablations/summary.json'); explain=read_json(OUT/'explainability/summary.json'); errors=read_json(OUT/'errors/summary.json')
    return audit,models,paired,calibration,subgroups,ablations,explain,errors

def subgroup_plot(subgroups):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    rows=[r for r in subgroups['results'] if r['model']=='transformer' and 'ci95' in r]
    fig,ax=plt.subplots(figsize=(10,max(5,len(rows)*.28)))
    points=[r['auroc'] for r in rows]; lo=[r['ci95']['auroc'][0] for r in rows]; hi=[r['ci95']['auroc'][1] for r in rows]
    ax.errorbar(points,range(len(rows)),xerr=[np.array(points)-lo,np.array(hi)-points],fmt='o',color='#277f99')
    ax.set(yticks=range(len(rows)),yticklabels=[f"{r['attribute']}: {r['group']} (n={r['n']}, events={r['positive']})" for r in rows],xlabel='AUROC with exploratory patient-bootstrap 95% intervals',xlim=(0,1),title='Transformer subgroups with sufficient support'); fig.tight_layout(); fig.savefig(OUT/'subgroups/transformer_forest.png',dpi=140); plt.close(fig)

def dashboard():
    if (OUT/'dashboard_summary.json').exists(): raise RuntimeError('Dashboard summary already exists; refusing overwrite')
    audit,models,paired,calibration,subgroups,ablations,explain,errors=load(); subgroup_plot(subgroups)
    explanation=explain['summary']
    text=f"Frozen Transformer logit IG, fixed-missingness training-mean baseline. In {len(explain['records'])} sampled cases: median relative completeness errors at 32/128/256 steps were {explanation['median_relative_completeness_32']:.4f}/{explanation['median_relative_completeness_128']:.4f}/{explanation['median_relative_completeness_256']:.4f}. Median feature/temporal rank correlations under small perturbations: {explanation['median_feature_spearman']:.3f}/{explanation['median_temporal_spearman']:.3f}. Attribution is numerical model sensitivity, not causation."
    plots=[{'path':f'calibration/{name}_reliability.png','label':name+' reliability diagram and score distribution'} for name in models]
    plots += [{'path':'paired/paired_bootstrap.png','label':'Paired patient-bootstrap model differences'},{'path':'subgroups/transformer_forest.png','label':'Exploratory supported Transformer subgroups'},{'path':'ablations/ablation_auroc.png','label':'Separately retrained feature and observation-window ablations'}]
    plots += [{'path':str(path.relative_to(OUT)).replace('\\','/'),'label':'Sampled held-out Integrated Gradients attribution'} for path in sorted((OUT/'explainability').glob('*_attribution.png'))[:2]]
    result={'run':RUN,'source_run':SOURCE,'cohort_cases':6119,'test_cases':1186,'test_patients':1146,'disclosure':'Internal retrospective research evaluation only. Transformer–GRU paired intervals include zero; no statistical superiority claim. The primary CSV workflow retains the selected frozen Transformer and its original uncalibrated score.','models':[{'name':name,'auroc':v['test']['auroc'],'auroc_ci':v['test']['bootstrap_95_ci']['auroc'],'auprc':v['test']['auprc'],'auprc_ci':v['test']['bootstrap_95_ci']['auprc'],'f1':v['test']['f1'],'brier':v['test']['brier_score']} for name,v in models.items()],'paired':paired['comparisons'],'calibration':[{'model':name,'method':v['selected_method'],'raw':v['test_raw'],'adjusted':v['test_calibrated']} for name,v in calibration.items()],'attributes':sorted({r['attribute'] for r in subgroups['results']}),'subgroups':subgroups['results'],'ablations':[{'variant':r['variant'],'window':r['maximum_observed_minutes'],'auroc':r['test']['auroc'],'auprc':r['test']['auprc'],'f1':r['test']['f1']} for r in ablations['variants']],'explainability_text':text,'plots':plots,'limitations':LIMITATIONS}
    save_json(OUT/'dashboard_summary.json',result)
    print('Dashboard evidence generated',flush=True)

def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(value).replace('|','/') for value in row)+' |' for row in rows])

def report():
    destination=ROOT/'results/RESEARCH_VALIDATION_REPORT.md'
    if destination.exists(): raise RuntimeError('Research report already exists; preserve it and choose a versioned destination')
    audit,models,paired,calibration,subgroups,ablations,explain,errors=load()
    verification=read_json(OUT/'final_verification.json')
    manifest=read_json(OUT/'preserved_manifest.json'); changes=[name for name,value in manifest.items() if digest(ROOT/name)!=value]
    if changes: raise RuntimeError('Protected original artifacts changed: '+str(changes))
    summary={'cohort':audit,'models':models,'paired':paired,'calibration':calibration,'subgroups':subgroups,'ablations':ablations,'explainability':explain,'errors':errors,'verification':verification,'protected_original_artifacts_unchanged':True,'protected_file_count':len(manifest),'limitations':LIMITATIONS}
    save_json(OUT/'FINAL_SUMMARY.json',summary)
    lines=['# RecoveryLens AI — Research Validation Report','',f'Analysis version: `{RUN}`. Frozen source experiment: `{SOURCE}`. This is **internal retrospective research evaluation**, not clinical validation.','', '## 1. Abstract','',f"Re-auditing all 6,388 VitalDB cases confirmed 6,119 valid survivor cases and patient-separated splits of 3,981/952/1,186. Frozen-model predictions were verified against archived scores. Paired patient bootstrap analysis found the Transformer–GRU AUROC difference to be {paired['comparisons'][0]['auroc']['difference']:.4f}, with a 95% interval spanning zero. Neural-model validation cross-fitting selected identity calibration; XGBoost selected Platt scaling with a slightly worse test Brier score. Nine new Transformer ablations and sampled attribution stability/completeness checks were executed. No original checkpoint was replaced.",'','## 2. Clinical motivation','','Postoperative length of stay is a hospital-utilization and recovery-related endpoint. It is also influenced by surgery complexity, comorbidities, discharge practices and nonphysiological constraints. These experiments investigate associations and computational prediction, without asserting treatment benefit or clinical readiness.','','## 3. Dataset description','','VitalDB is a single-source retrospective surgical dataset. This project uses seven configured numeric physiological channels: HR, SpO2, SBP, DBP, MAP, EtCO2, and RR. Raw files are public deidentified recordings; unrelated high-frequency waveforms are not model inputs. There are 31,082 verified numeric track files. Official field definitions: https://vitaldb.net/dataset/.','','## 4. Cohort selection','',table(['Stage','Cases'],audit['flow']),'',f"Exclusions overlap: {audit['original_exclusions_overlapping']}. Two cases have both a negative interval and in-hospital death, so the 27 negative intervals plus 57 deaths yield 82 unique exclusions. There are no missing/nonfinite discharge timestamps. Of 6,306 outcome-eligible survivors, 6,305 have at least one configured track, 6,179 have at least three tracks, and 60 fail the fixed signal-quality policy.",'',audit['population'],'',f"There are {audit['unique_patients']} unique included patients, {audit['patients_with_multiple_cases']} patients with multiple operations, {audit['extra_cases_beyond_one_per_patient']} extra cases, and a maximum of {audit['max_cases_per_patient']} operations for one patient. No patient crosses train/validation/test. All initially examined patients are restricted to expanded training.",'',table(['Split','Cases','Patients','Prolonged stays'],[[name,v['cases'],v['patients'],v['positive']] for name,v in audit['splits'].items()]),'', 'The first CPU verification attempt is retained in `cohort_audit.json`. CPU GRU scores differed from archived CUDA scores by at most 0.0001578033. Original CUDA torch 2.5.1 and batch size 16 reproduced the neural predictions. The authoritative passed audit is `cohort_integrity_verified.json`; exact archived test probabilities are used after frozen-model reproduction. No cohort correction or baseline retraining was necessary.','','## 5. Outcome definition','',f"Elapsed postoperative stay is `(dis - opend) / 86400` days. VitalDB documents both fields as seconds relative to recording start. Negative intervals, invalid/missing outcome endpoints and in-hospital deaths are excluded. Prolonged stay is strictly greater than the **training-only 75th percentile: {audit['threshold_days']:.10f} days**. This is a statistical threshold, not a clinically established standard. Source EMR dates cannot be independently verified.",'','## 6. Model architecture','','Frozen Transformer: seven standardized physiology channels and seven observation indicators; 64-dimensional embedding, sinusoidal positions, two encoder layers, four attention heads, masked pooling, and a logit head. GRU uses packed sequences. XGBoost uses mean/std/min/max of normalized signals and missingness flags. Minute medians, broad artifact limits, train-only normalization, explicit padding masks, and a 720-minute cap are unchanged. Artifact limits are applied after minute aggregation and may miss brief within-minute artifacts.','','## 7. Experimental methodology','','All analyses require the passed cohort audit. Models use identical held-out cases and patient identifiers. Original checkpoints, datasets, preprocessing, app files and experimental results are hash-protected and were not overwritten. The holdout was already examined during the prior experiment; this secondary evaluation is exploratory, not a fresh independent validation. Bootstrap intervals condition on fitted models and fixed outcome labels. No analysis here establishes external or prospective validity.','','## 8. Statistical comparison','','Paired 2,000-resample patient-cluster bootstrap (seed 20261110). Every model uses the same sampled patients in each replicate. All 2,000 resamples contained both outcome classes. Positive differences favor the first named model.','',table(['Comparison','AUROC difference','AUROC 95% CI','AUPRC difference','AUPRC 95% CI'],[[f"{r['first']} minus {r['second']}",f"{r['auroc']['difference']:.4f}",f"[{r['auroc']['ci95'][0]:.4f}, {r['auroc']['ci95'][1]:.4f}]",f"{r['auprc']['difference']:.4f}",f"[{r['auprc']['ci95'][0]:.4f}, {r['auprc']['ci95'][1]:.4f}]"] for r in paired['comparisons']]),'','Transformer–GRU intervals include zero for both metrics; a superiority claim is unsupported. Neural-versus-XGBoost marginal intervals exclude zero, providing conditional exploratory evidence of a discrimination difference. Intervals are not multiplicity-adjusted and cannot establish clinical superiority. Bootstrap distributions are saved in `paired/bootstrap_distributions.csv`.','','## 9. Calibration','','Calibration methods were chosen by five-fold patient-group cross-fitted **validation** Brier score among identity, Platt scaling on clipped logits, and isotonic regression. The selected method was refitted using all validation cases only. Test outcomes were never used to fit or choose deployable calibration transformations. Reusing the base-model validation set means this is not independent nested outer validation.','',table(['Model','Selected method','Raw Brier','Adjusted Brier','Raw intercept','Raw slope','Raw ECE'],[[name,r['selected_method'],f"{r['test_raw']['brier']:.5f}",f"{r['test_calibrated']['brier']:.5f}",f"{r['test_raw']['calibration_intercept']:.4f}",f"{r['test_raw']['calibration_slope']:.4f}",f"{r['test_raw']['ece']:.5f}"] for name,r in calibration.items()]),'','Calibration intercept and slope come from joint diagnostic logistic regression on test predictions. Calibration-in-the-large is additionally estimated with slope fixed to one. These test regressions describe miscalibration and are **not deployed calibration models**. ECE uses ten fixed equal-width bins, including weights for populated bins. Ideal joint intercept/slope are zero/one; ECE depends on binning and sample size.','', 'Identity was selected for both neural models: their outputs remain uncalibrated model scores, not clinically validated probabilities. Platt scaling selected for XGBoost worsened test Brier slightly; validation improvement does not guarantee test improvement. Raw/calibrated diagnostics, bin data, over/underprediction summaries, OOF scores and separate JSON calibration parameters are retained.','', '![Transformer reliability](statistical_validation/'+RUN+'/calibration/transformer_reliability.png)','','## 10. Subgroup analysis','',f"Available attributes: age, sex, surgery type, actual surgical duration, ASA, and emergency/elective status. Test-set missing values: {subgroups['missing_attributes_in_test']}. The analysis produced {len(subgroups['results'])} model/group cells; {sum(not r['stable_metrics_reported'] for r in subgroups['results'])} are suppressed for insufficient support. Counts are always retained.",'','Performance metrics require at least 50 cases and ten events and ten non-events. Confidence intervals additionally require 100 cases, 20 events/non-events, and 30 patient clusters; they use 1,000 patient-cluster resamples. Subgroup comparisons are descriptive, unadjusted and potentially confounded; overlapping intervals do not prove equality, and differences do not establish fairness or causality.','',table(['Transformer group','n','Events','AUROC','AUPRC','Sensitivity','Specificity','Raw Brier'],[[r['attribute']+': '+r['group'],r['n'],r['positive']]+([f"{r[k]:.3f}" for k in ['auroc','auprc','sensitivity','specificity']]+[f"{r['calibration_raw']['brier']:.4f}"] if r['stable_metrics_reported'] else ['Withheld']*5) for r in subgroups['results'] if r['model']=='transformer']), '', 'Complete three-model subgroup values, supported intervals and calibration diagnostics are in `subgroups/summary.json` and `subgroups/subgroups.csv`.','','## 11. Ablation results','','Nine separately retrained **Transformer-family** experiments: six feature sets at the full window, plus all-feature first-30/60/90-minute models. This is not a 6-by-4 factorial design and does not retrain all three model families. Every variant retains the same cohort, labels, and patient splits. Input embedding dimensions change with the features; the no-flags model has seven inputs instead of fourteen. All variants use the RTX 4070 SUPER, AdamW 1e-4, batch 16, seed 42, maximum 40 epochs and validation-loss early stopping.','',table(['Variant','Max minutes','AUROC','AUPRC','F1','GPU loop seconds','Epochs'],[[r['variant'],r['maximum_observed_minutes'],f"{r['test']['auroc']:.4f}",f"{r['test']['auprc']:.4f}",f"{r['test']['f1']:.4f}",f"{r['training_seconds']:.2f}",r['epochs_completed']] for r in ablations['variants']]),'','Early models use only `raw_sequence[:30/60/90]` and refit normalization using the same allowed training prefixes, so no later measurements enter early inputs or scaling. Surgeries shorter than the cap remain included; these are up-to-prefix predictions, not a strict ongoing-surgery landmark cohort. Full-window models represent end-of-recording prediction, capped at 720 minutes. Surgery duration/recording length remains visible through masks and positions, even in one-signal models. Feature-set differences do not isolate physiological causation. Removing flags still leaves implicit missingness through mean imputation. Every variant has a separate new checkpoint and retained validation/test results; no ablation model is promoted.','','## 12. Explainability','',explain['baseline'],'',explain['target'],'',explain['sample_policy'],'',explain['perturbation_policy'],'',table(['Check','Computed summary'],[[key,f'{value:.6f}' if isinstance(value,float) else str(value)] for key,value in explain['summary'].items()]),'','The existing 32-step implementation is checked against a direct trapezoidal reimplementation, the pre-sigmoid attribution target, exact checkpoint normalization, observed-value masks, minute alignment and masked padding. Completeness compares the attribution sum with the logit difference from the fixed-missingness baseline. Numerical convergence is assessed at 32/128/256 steps; rank stability uses three small perturbations per sampled case. Finite-step completeness errors and unstable cases must be interpreted, not hidden. Neither the baseline nor attribution establishes clinical causality. The original working explanation implementation remains unchanged.','','## 13. Error analysis','',table(['Model','TP','FP','FN','TN','FP >50% missing','FN >50% missing'],[[name]+[r['groups'].get(k,{}).get('n',0) for k in ['TP','FP','FN','TN']]+[r['groups'].get(k,{}).get('substantial_missingness_gt50pct',0) for k in ['FP','FN']] for name,r in errors.items()]),'','Per-case false-positive and false-negative files include channel medians, physiological variability IQR, consecutive-minute absolute changes, observed fractions, HR>100 / MAP<65 / SpO2<94 fractions, surgery categories and postoperative-stay ranges. These thresholds are descriptive pattern markers, not treatment recommendations. Aggregates by TP/FP/FN/TN and probability-distribution/confusion-matrix plots are saved for all three models. Associations are unadjusted and cannot be interpreted as causes of postoperative stay or prediction error.','','## 14. Limitations','']+['- '+value for value in LIMITATIONS]+['','## 15. Future work','','External multicenter replication, prospective silent evaluation, predeclared clinical decision thresholds, competing-risk or mortality-inclusive endpoints, nested calibration validation, multiple-seed/repeated-split ablations, strict early landmarks, clinical artifact review, adjustment for procedure/discharge confounding, and independently evaluated deployment controls remain necessary.','','## 16. Conclusion','',f"The original 6,119-case survivor cohort and frozen predictions are verified. Transformer–GRU uncertainty does not support statistical superiority. Calibration selection retained the neural-model scores; the research dashboard explicitly labels them uncalibrated. The completed analyses are internal retrospective research, not clinical deployment validation. Final automated verification: **{verification['tests_summary']}**. Version-asserted browser checks verified the original CSV workflow, calibration disclosure, charts, subgroup controls, explainability, mobile layout and augmented PDF. All {len(manifest)} protected original files remain unchanged.",'','## Artifacts and launch','','The research dashboard is an additive entry point: `python research_app.py` (same localhost port 5050). The original `app.py`, templates, static files, active checkpoint and existing experiment artifacts remain unchanged. See `research/README.md` for reproduction and preservation details.','', 'Primary evidence directory: `results/statistical_validation/'+RUN+'/`. Calibration configurations: `models/calibration/'+RUN+'/`. Ablation checkpoints: `models/checkpoints/'+RUN+'/ablations/`.','', '## Method references','','- VitalDB field dictionary and dataset: https://vitaldb.net/dataset/','- Probability calibration documentation: https://scikit-learn.org/stable/modules/calibration.html','- Sundararajan, Taly, Yan. Axiomatic Attribution for Deep Networks: https://arxiv.org/abs/1703.01365','']
    destination.write_text('\n'.join(lines),encoding='utf-8')
    print('Research report written:',destination,flush=True)

if __name__=='__main__':
    p=argparse.ArgumentParser(); p.add_argument('--dashboard',action='store_true'); args=p.parse_args()
    dashboard() if args.dashboard else report()
